(6327881, 937273, 96751, '<td valign="top">Amazing shoes.  A bit harsh with the lighting, though.</td>', 'Amazing shoes.  A bit harsh with the lighting, though.', '2011-02-23 00:32:14.000000', NULL, 1),
(6327905, 937270, 96751, '<td valign="top">Nice pov and subject, but a bit dark.</td>', 'Nice pov and subject, but a bit dark.', '2011-02-23 00:42:03.000000', NULL, 1),
(6327906, 937201, 96751, '<td valign="top">Interesting, um, construction...</td>', 'Interesting, um, construction...', '2011-02-23 00:42:31.000000', NULL, 1),
(6327909, 937051, 96751, '<td valign="top">Beautiful light.  Very clean image.  I love the right shoe, and the chair leg, but the position of the left shoe seems ungainly.</td>', 'Beautiful light.  Very clean image.  I love the right shoe, and the chair leg, but the position of the left shoe seems ungainly.', '2011-02-23 00:43:36.000000', NULL, 1),
(6327913, 937254, 96751, '<td valign="top">The first image I''ve come across that incorporates "lonely" on the composition.</td>', 'The first image I''ve come across that incorporates "lonely" on the composition.', '2011-02-23 00:44:16.000000', NULL, 1),
(6327919, 936579, 96751, '<td valign="top">Very clean and well taken, if a bit heavy handed on the theme.  But it is one of the few that expresses "lonely".</td>', 'Very clean and well taken, if a bit heavy handed on the theme.  But it is one of the few that expresses "lonely".', '2011-02-23 00:46:32.000000', NULL, 1),
(6327930, 937316, 15511, '<td valign="top">Heh, heh. Great Camo, but it jumps right out at me. Easily one of the best in the challenge.</td>', 'Heh, heh. Great Camo, but it jumps right out at me. Easily one of the best in the challenge.', '2011-02-23 00:49:41.000000', NULL, 1),
(6327932, 937167, 1686, '<td valign="top">Naughty</td>', 'Naughty', '2011-02-23 00:50:20.000000', NULL, 1),
(6327940, 937059, 96751, '<td valign="top">How incredibly artistic and moody.  And WHAT GREAT SHOES!!!  I love this low-tech lighting approach, and the sumptuous shadows coveting secrets.</td>', 'How incredibly artistic and moody.  And WHAT GREAT SHOES!!!  I love this low-tech lighting approach, and the sumptuous shadows coveting secrets.', '2011-02-23 00:51:44.000000', NULL, 1),
(6327942, 936493, 96751, '<td valign="top">Powerful image.  Sad.</td>', 'Powerful image.  Sad.', '2011-02-23 00:52:54.000000', NULL, 1),
(6327944, 937222, 60224, '<td valign="top">great idea!!</td>', 'great idea!!', '2011-02-23 00:53:22.000000', NULL, 1),
(6327946, 937206, 96751, '<td valign="top">Beautiful composition and leading - if blurry - lines.  A palpable sense of loneliness, one of only a handful.</td>', 'Beautiful composition and leading - if blurry - lines.  A palpable sense of loneliness, one of only a handful.', '2011-02-23 00:54:04.000000', NULL, 1),
(6327953, 937174, 96751, '<td valign="top">Definitely looking dejected.  Love how the shoes are set up, and the pine cone is a nice touch, but a stucco wall?  Really?</td>', 'Definitely looking dejected.  Love how the shoes are set up, and the pine cone is a nice touch, but a stucco wall?  Really?', '2011-02-23 00:54:52.000000', NULL, 1),
(6327955, 936412, 96751, '<td valign="top">Glamor shot, very lovely.  No loneliness to be seen anywhere...</td>', 'Glamor shot, very lovely.  No loneliness to be seen anywhere...', '2011-02-23 00:55:25.000000', NULL, 1),
(6327958, 937316, 96751, '<td valign="top">Gorgeous show, a real eye pleaser, and will most certainly do well, and possibly even ribbon.  At the very least on the front page.  But I am not seeing how these are "lonely" shoes.  Eye candy with no emotion for me.</td>', 'Gorgeous show, a real eye pleaser, and will most certainly do well, and possibly even ribbon.  At the very least on the front page.  But I am not seeing how these are "lonely" shoes.  Eye candy with no emotion for me.', '2011-02-23 00:56:22.000000', NULL, 1),
(6327967, 936923, 96751, '<td valign="top">Thank goodness.  A well-done image with emotional content.  Love the desat, and the killer shadow, the shoes caught in a tangle of hangers.  Just wish the tip had not been cut off.</td>', 'Thank goodness.  A well-done image with emotional content.  Love the desat, and the killer shadow, the shoes caught in a tangle of hangers.  Just wish the tip had not been cut off.', '2011-02-23 00:59:54.000000', NULL, 1),
(6327968, 936758, 96751, '<td valign="top">Sad, flattened shoe.  Love the terrazzo</td>', 'Sad, flattened shoe.  Love the terrazzo', '2011-02-23 01:00:33.000000', NULL, 1),
(6327970, 937157, 96751, '<td valign="top">Very extravagant set.  Very nature morte with the fish and seaweed.</td>', 'Very extravagant set.  Very nature morte with the fish and seaweed.', '2011-02-23 01:01:23.000000', NULL, 1),
(6327971, 937300, 96751, '<td valign="top">Great lighting and sense of wilderness.</td>', 'Great lighting and sense of wilderness.', '2011-02-23 01:01:39.000000', NULL, 1),
(6327972, 936630, 96751, '<td valign="top">Fun, high-key image.  Cumberson title.</td>', 'Fun, high-key image.  Cumberson title.', '2011-02-23 01:02:22.000000', NULL, 1),
(6327976, 936630, 114285, '<td valign="top">Love the processing, and well composed.</td>', 'Love the processing, and well composed.', '2011-02-23 01:03:51.000000', NULL, 1),
(6327977, 937263, 96751, '<td valign="top">You''ve got to be kidding!  A pity there is so much going on all around, we almost miss the gorgeous birdie!</td>', 'You''ve got to be kidding!  A pity there is so much going on all around, we almost miss the gorgeous birdie!', '2011-02-23 01:03:58.000000', NULL, 1),
(6327978, 936493, 114285, '<td valign="top">Lol, I feel dizzy, good stuff.</td>', 'Lol, I feel dizzy, good stuff.', '2011-02-23 01:04:30.000000', NULL, 1),
(6327979, 936516, 96751, '<td valign="top">Love the smoke coming from them, but the head on composition is just a little static.  Great lighting and detail.</td>', 'Love the smoke coming from them, but the head on composition is just a little static.  Great lighting and detail.', '2011-02-23 01:04:35.000000', NULL, 1),
(6327980, 936565, 114285, '<td valign="top">Great stuff, ribbon for you.</td>', 'Great stuff, ribbon for you.', '2011-02-23 01:04:55.000000', NULL, 1),
(6327981, 937213, 96751, '<td valign="top">Nice!  Great pov and killer grain and light.</td>', 'Nice!  Great pov and killer grain and light.', '2011-02-23 01:05:02.000000', NULL, 1),
(6327983, 937208, 114285, '<td valign="top">Man they are too high for me, nice photo.</td>', 'Man they are too high for me, nice photo.', '2011-02-23 01:05:36.000000', NULL, 1),
(6327985, 936677, 96751, '<td valign="top">I love this.  The radiating lines seem like a rhythmic dance, interrupted by a couple of feet.  Well done!</td>', 'I love this.  The radiating lines seem like a rhythmic dance, interrupted by a couple of feet.  Well done!', '2011-02-23 01:05:46.000000', NULL, 1),
(6327986, 937073, 114285, '<td valign="top">Funky I like it.</td>', 'Funky I like it.', '2011-02-23 01:05:55.000000', NULL, 1),
(6327987, 937289, 96751, '<td valign="top">Nice!  Beautiful conversion, and sumptuous detail.</td>', 'Nice!  Beautiful conversion, and sumptuous detail.', '2011-02-23 01:06:06.000000', NULL, 1),
(6327992, 937006, 114285, '<td valign="top">Nice bokeh, and well composed.</td>', 'Nice bokeh, and well composed.', '2011-02-23 01:07:12.000000', NULL, 1),
(6327994, 937194, 96751, '<td valign="top">Points for creating a visual puzzle, and more points for kitties.  But this riddle wrapped in an enigma is about a lot of things, least of all shoes.  Should do well with the PH crowd :-)</td>', 'Points for creating a visual puzzle, and more points for kitties.  But this riddle wrapped in an enigma is about a lot of things, least of all shoes.  Should do well with the PH crowd :-)', '2011-02-23 01:07:29.000000', NULL, 1),
(6327995, 937013, 114285, '<td valign="top">Great angle, one of the better ones, will probably ribbon.</td>', 'Great angle, one of the better ones, will probably ribbon.', '2011-02-23 01:08:02.000000', NULL, 1),
(6327998, 936214, 96751, '<td valign="top">OMG!  There really ARE wooden shoes!  Marvelous find.</td>', 'OMG!  There really ARE wooden shoes!  Marvelous find.', '2011-02-23 01:08:24.000000', NULL, 1),
