(6328049, 936465, 66641, '<td valign="top">simple, but has a great feel to it</td>', 'simple, but has a great feel to it', '2011-02-23 01:29:46.000000', NULL, 1),
(6328056, 936616, 96751, '<td valign="top">Quite a setup.  Gorgeous stretch of road, marvelous textures and tonal range.</td>', 'Quite a setup.  Gorgeous stretch of road, marvelous textures and tonal range.', '2011-02-23 01:32:35.000000', NULL, 1),
(6328058, 937052, 96751, '<td valign="top">There is such promise in this image.  I think a little more attention could be put in the placement/position of the shoes, to give a stronger relationship between them.  But the light is gorgeous and the conversion perfect.</td>', 'There is such promise in this image.  I think a little more attention could be put in the placement/position of the shoes, to give a stronger relationship between them.  But the light is gorgeous and the conversion perfect.', '2011-02-23 01:33:57.000000', NULL, 1),
(6328061, 937074, 96751, '<td valign="top">Epic.  Gorgeous everything.  Not sure where to look first.  The landscape is so overpowering, that the shoes are the least interesting part.  The fact that they are not in a particularly interesting position doesn''t help.  In a landscape challenge, this would be an 8.  Of course, I am always contrary to the trends and this will likely ribbon.</td>', 'Epic.  Gorgeous everything.  Not sure where to look first.  The landscape is so overpowering, that the shoes are the least interesting part.  The fact that they are not in a particularly interesting position doesn''t help.  In a landscape challenge, this would be an 8.  Of course, I am always contrary to the trends and this will likely ribbon.', '2011-02-23 01:36:30.000000', NULL, 1),
(6328065, 937076, 96751, '<td valign="top">An image that DEMANDS to be looked at.  How utterly arrogant and marvelous.</td>', 'An image that DEMANDS to be looked at.  How utterly arrogant and marvelous.', '2011-02-23 01:38:21.000000', NULL, 1),
