(6328802, 936516, 124815, '<td valign="top">Makes so much sense! In my view, the photo needs a little more "air" - I would have left more negative space around. Hope no shoe suffered in the process, just the feet! Top 10</td>', 'Makes so much sense! In my view, the photo needs a little more "air" - I would have left more negative space around. Hope no shoe suffered in the process, just the feet! Top 10', '2011-02-23 12:13:56.000000', NULL, 1),
(6328805, 937222, 124815, '<td valign="top">Very good idea! Bravo. I am bothered by seeing too much at the top of the image. I would crop the top of the stairs. A wooden or stone stair would have worked marvels. 7</td>', 'Very good idea! Bravo. I am bothered by seeing too much at the top of the image. I would crop the top of the stairs. A wooden or stone stair would have worked marvels. 7', '2011-02-23 12:14:47.000000', NULL, 1),
(6328806, 937020, 124815, '<td valign="top">Very, very funny and imaginative.</td>', 'Very, very funny and imaginative.', '2011-02-23 12:15:01.000000', NULL, 1),
(6328808, 937180, 124815, '<td valign="top">Best of the crop!</td>', 'Best of the crop!', '2011-02-23 12:16:01.000000', NULL, 1),
(6328812, 936923, 124815, '<td valign="top">Too bad that the tip of the shoe is cropped. Nice tonality.</td>', 'Too bad that the tip of the shoe is cropped. Nice tonality.', '2011-02-23 12:18:14.000000', NULL, 1),
(6328815, 937304, 124815, '<td valign="top">Interesting idea. Way too processed for my taste even if the stone quality would explain it. The proportion between elements is not too well balanced or defined.<br/>Somewhere between 5 and 6 (marked here)</td>', 'Interesting idea. Way too processed for my taste even if the stone quality would explain it. The proportion between elements is not too well balanced or defined.Somewhere between 5 and 6 (marked here)', '2011-02-23 12:22:21.000000', NULL, 1),
(6328821, 937072, 124815, '<td valign="top">Nice but crowded photo. Of course that it''s irresistibly cute but ....it has too much of a good thing. The boots are too much cherished to be lonely. And what does the dog want?</td>', 'Nice but crowded photo. Of course that it''s irresistibly cute but ....it has too much of a good thing. The boots are too much cherished to be lonely. And what does the dog want?', '2011-02-23 12:25:21.000000', NULL, 1),
(6328825, 936537, 124815, '<td valign="top">Beautiful picture BUT ...personally, I have no use for a border. Somehow, the words "athletes" "God" and the presences of roses are canceling each other. It''s more like a congratulation card for a great dancer. 6</td>', 'Beautiful picture BUT ...personally, I have no use for a border. Somehow, the words "athletes" "God" and the presences of roses are canceling each other. It''s more like a congratulation card for a great dancer. 6', '2011-02-23 12:29:03.000000', NULL, 1),
(6328831, 937213, 124815, '<td valign="top">Oneiroi comes from the same family as Lupercus! Wished for shoes from a more similar family.</td>', 'Oneiroi comes from the same family as Lupercus! Wished for shoes from a more similar family.', '2011-02-23 12:31:59.000000', NULL, 1),
(6328847, 937212, 124815, '<td valign="top">This sky used to be blue!</td>', 'This sky used to be blue!', '2011-02-23 12:40:43.000000', NULL, 1),
(6328859, 936299, 128166, '<td valign="top">If you left out the hand, I would have graded it higher. Okay the title wouldn''t be correct anymore, but I love the lines of the shoes in this shot and the hand "kills" it a bit to me.</td>', 'If you left out the hand, I would have graded it higher. Okay the title wouldn''t be correct anymore, but I love the lines of the shoes in this shot and the hand "kills" it a bit to me.', '2011-02-23 12:49:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6328865, 937170, 128166, '<td valign="top">I get dizzy looking at this. Don''t know if that''s a good or a bad thing</td>', 'I get dizzy looking at this. Don''t know if that''s a good or a bad thing', '2011-02-23 12:53:10.000000', NULL, 1),
(6328868, 937222, 128166, '<td valign="top">Nice idea but too bad that the pants seem to be a bit behind the shoes (as in closer to the viewer than the shoes).</td>', 'Nice idea but too bad that the pants seem to be a bit behind the shoes (as in closer to the viewer than the shoes).', '2011-02-23 12:54:14.000000', NULL, 1),
(6328901, 937122, 6202, '<td valign="top">Gosh you must be my neighbor...my boots looked just like that yesterday morning...awesome capture of reality.</td>', 'Gosh you must be my neighbor...my boots looked just like that yesterday morning...awesome capture of reality.', '2011-02-23 13:16:09.000000', NULL, 1),
(6328905, 937270, 6202, '<td valign="top">good use of lighting.</td>', 'good use of lighting.', '2011-02-23 13:17:12.000000', NULL, 1),
(6328914, 936416, 6202, '<td valign="top">A picture is worth a 1000 words this one is worth several 1000 words.</td>', 'A picture is worth a 1000 words this one is worth several 1000 words.', '2011-02-23 13:23:51.000000', NULL, 1),
(6328917, 937186, 6202, '<td valign="top">What an emotional capture.  That dog obviously loves the owner of the work boots.</td>', 'What an emotional capture.  That dog obviously loves the owner of the work boots.', '2011-02-23 13:26:41.000000', NULL, 1),
(6328921, 936926, 54446, '<td valign="top">I voted a "7" on this.  Superb composition.  Great clarity and detail on the wet boot.  The narrow dof with pleasant bg bokeh really throws the eye to the subject.  I love the luminous glow on the water and the rippled reflections.  The fishing line is just right.  (My filament line would be invisible.)  Outstanding tonal range.  Excellent b&amp;w conversion.  I also love the shot angle, which is low..... like you were in the water, below the gunnel of the boat.</td>', 'I voted a "7" on this.  Superb composition.  Great clarity and detail on the wet boot.  The narrow dof with pleasant bg bokeh really throws the eye to the subject.  I love the luminous glow on the water and the rippled reflections.  The fishing line is just right.  (My filament line would be invisible.)  Outstanding tonal range.  Excellent b&w conversion.  I also love the shot angle, which is low..... like you were in the water, below the gunnel of the boat.', '2011-02-23 13:27:47.000000', NULL, 1),
