(6330746, 937029, 85430, '<td valign="top">Nice composition. Lovely lines, they effectively break the boring monotony. I like the white subject over dark bg. Really nice.</td>', 'Nice composition. Lovely lines, they effectively break the boring monotony. I like the white subject over dark bg. Really nice.', '2011-02-24 09:19:24.000000', NULL, 1),
(6330747, 936677, 85430, '<td valign="top">Great geometry. I like the white lines that break the massive dark bg. Great photo.</td>', 'Great geometry. I like the white lines that break the massive dark bg. Great photo.', '2011-02-24 09:20:51.000000', NULL, 1),
(6330749, 936416, 85430, '<td valign="top">I like the middleground focus. Overall a nice photo.</td>', 'I like the middleground focus. Overall a nice photo.', '2011-02-24 09:22:12.000000', NULL, 1),
(6330750, 936457, 85430, '<td valign="top">Good composition, but i feel the over-blown highlights is just too much for my taste. 6 would be fair?</td>', 'Good composition, but i feel the over-blown highlights is just too much for my taste. 6 would be fair?', '2011-02-24 09:23:24.000000', NULL, 1),
(6330752, 937020, 85430, '<td valign="top">Now that''s a story. I like the concept and execution. 7</td>', 'Now that''s a story. I like the concept and execution. 7', '2011-02-24 09:24:12.000000', NULL, 1),
(6330753, 936516, 85430, '<td valign="top">whoa! burnout indeed. While this is a really nice photo, a portrait if you may call it, and I really like it, I don''t think it shows a sense of loneliness that the challenge was asking. still a 6 from me.</td>', 'whoa! burnout indeed. While this is a really nice photo, a portrait if you may call it, and I really like it, I don''t think it shows a sense of loneliness that the challenge was asking. still a 6 from me.', '2011-02-24 09:26:12.000000', NULL, 1),
(6330755, 937074, 85430, '<td valign="top">great seascape. really beautiful. while i dont usually go for black and white landscapes and seascapes, i find so much to like in this photo. I feel the shoes was just put in there to meet the challenge though. This is more of the beautiful seascape than the shoe. And honestly, if i find myself lost in a view as lovely as this, I wouldn''t feel lonely at all. The shoes actually show this. They are not lonely, they are in the mood for party. 6 would be fair.</td>', 'great seascape. really beautiful. while i dont usually go for black and white landscapes and seascapes, i find so much to like in this photo. I feel the shoes was just put in there to meet the challenge though. This is more of the beautiful seascape than the shoe. And honestly, if i find myself lost in a view as lovely as this, I wouldn''t feel lonely at all. The shoes actually show this. They are not lonely, they are in the mood for party. 6 would be fair.', '2011-02-24 09:30:34.000000', NULL, 1),
(6330756, 937292, 85430, '<td valign="top">i feel some great drama in this shot. beautifully done.</td>', 'i feel some great drama in this shot. beautifully done.', '2011-02-24 09:31:22.000000', NULL, 1),
(6330762, 936641, 85430, '<td valign="top">That shoe is classy and elegant. The loneliness must be well hidden somewhere. Yeah, that''s what classy and elegant people do. They hide the loneliness and put up a good public appearance.</td>', 'That shoe is classy and elegant. The loneliness must be well hidden somewhere. Yeah, that''s what classy and elegant people do. They hide the loneliness and put up a good public appearance.', '2011-02-24 09:33:43.000000', NULL, 1),
(6330824, 936235, 66641, '<td valign="top">very moody, nice</td>', 'very moody, nice', '2011-02-24 10:45:02.000000', NULL, 1),
(6330827, 937058, 66641, '<td valign="top">cute</td>', 'cute', '2011-02-24 10:47:33.000000', NULL, 1),
(6330895, 936931, 118396, '<td valign="top">I think this shot would score a lot higher if the shadow wasn''t in the background - just a touch distracting.</td>', 'I think this shot would score a lot higher if the shadow wasn''t in the background - just a touch distracting.', '2011-02-24 12:00:11.000000', NULL, 1),
(6330897, 936822, 118396, '<td valign="top">Very clever!  I like it!</td>', 'Very clever!  I like it!', '2011-02-24 12:00:39.000000', NULL, 1),
(6330899, 936557, 118396, '<td valign="top">I love the set up - great job!</td>', 'I love the set up - great job!', '2011-02-24 12:01:01.000000', NULL, 1),
(6330902, 936803, 118396, '<td valign="top">I had a hard time finding the shoes at first - probably would have given it a higher score if the shoes were a little more prominent.  Nice streetscape though!</td>', 'I had a hard time finding the shoes at first - probably would have given it a higher score if the shoes were a little more prominent.  Nice streetscape though!', '2011-02-24 12:02:44.000000', NULL, 1);
